SELECT id, reconcile_date, reconcile_type, initiation_id, expected_amount, actual_amount, diff_amount, diff_pct, status, detail, tenant_id, provider_trace_id, created_at, updated_at, deleted
FROM pmis_reconcile_daily
WHERE deleted = 0
  AND reconcile_date = #{date}
  AND reconcile_type = #{type}

      AND initiation_id = #{initiationId}
      AND initiation_id IS NULL

LIMIT 1

SELECT id, reconcile_date, reconcile_type, initiation_id, expected_amount, actual_amount, diff_amount, diff_pct, status, detail, tenant_id, provider_trace_id, created_at, updated_at, deleted
FROM pmis_reconcile_daily
WHERE deleted = 0
  AND reconcile_date BETWEEN #{from} AND #{to}
  AND status = #{status}
ORDER BY reconcile_date DESC, reconcile_type
